{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e2-harness-vs-product-sonnet-t5-sealed/cell-0qJ6gp/src/address.js","content":"/**
 * Cell address helpers: parsing "A1"-style tokens, converting between
 * column letters and numbers, expanding ranges, and sorting addresses in
 * ascending column-then-row order.
 */

const ADDR_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/**
 * Parse an address token (assumed already upper-cased, though this also
 * accepts lower case for convenience) into { col, row }. Returns null when
 * the token is not a syntactically valid address, or the row is out of the
 * addressable range (1..999, and the digit run is 1-3 digits so 999 is the
 * natural ceiling).
 */
export function parseAddress(token) {
  const m = ADDR_RE.exec(token)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1 || row > 999) return null
  const col = colToNumber(m[1].toUpperCase())
  return { col, row }
}

export function colToNumber(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

export function numberToCol(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

export function formatAddress(col, row) {
  return `${numberToCol(col)}${row}`
}

/**
 * Expand a range given its two corner tokens (in any orientation) into the
 * list of address strings it covers, in ascending column order and, within
 * a column, ascending row order. Returns null if either corner is not a
 * valid addressable-range address.
 */
export function expandRange(startToken, endToken) {
  const s = parseAddress(startToken)
  const e = parseAddress(endToken)
  if (!s || !e) return null
  const c1 = Math.min(s.col, e.col)
  const c2 = Math.max(s.col, e.col)
  const r1 = Math.min(s.row, e.row)
  const r2 = Math.max(s.row, e.row)
  const out = []
  for (let c = c1; c <= c2; c++) {
    for (let r = r1; r <= r2; r++) {
      out.push(formatAddress(c, r))
    }
  }
  return out
}

export function sortAddresses(list) {
  return [...list].sort((a, b) => {
    const pa = parseAddress(a)
    const pb = parseAddress(b)
    if (pa.col !== pb.col) return pa.col - pb.col
    return pa.row - pb.row
  })
}
"}

