chunk.argumentsDelta:
{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e2-harness-vs-product-sonnet-t5-sealed/cell-0qJ6gp/src/sheet.js","content":"/**
 * Parses the sheet text format read from standard input into a
 * Map<address, content>.
 */

import { parseAddress } from './address.js'

export class CliError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]

    let j = 0
    while (j < raw.length && (raw[j] === ' ' || raw[j] === '\t')) j++
    const rest = raw.slice(j)

    if (rest === '' || rest[0] === '#') continue

    let k = 0
    while (k < rest.length && rest[k] !== ' ' && rest[k] !== '\t') k++
    const addrRaw = rest.slice(0, k)
    const addr = addrRaw.toUpperCase()

    if (!parseAddress(addr)) {
      throw new CliError(lineNo, `invalid cell address ${addr}`)
    }

    let m = k
    while (m < rest.length && (rest[m] === ' ' || rest[m] === '\t')) m++
    const content = rest.slice(m)

    if (cells.has(addr)) {
      throw new CliError(lineNo, `cell ${addr} is declared twice`)
    }

    cells.set(addr, content)
  }

  return cells
}
"}

