 * Tokenizer for formula bodies (the text after the leading `=`).
 */

function isDigit(ch) {
  return ch >= '0' && ch <= '9'
}

function isAlpha(ch) {
  return (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z')
}

export function tokenize(src) {
  const tokens = []
  let i = 0
  const n = src.length

  while (i < n) {
    const ch = src[i]

    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }

    if (isDigit(ch)) {
      let j = i + 1
      while (j < n && isDigit(src[j])) j++
      if (src[j] === '.' && isDigit(src[j + 1])) {
        j++
        while (j < n && isDigit(src[j])) j++
      }
      tokens.push({ type: 'NUMBER', value: src.slice(i, j) })
      i = j
      continue
    }

    if (isAlpha(ch)) {
      let j = i + 1
      while (j < n && isAlpha(src[j])) j++
      while (j < n && isDigit(src[j])) j++
      tokens.push({ type: 'WORD', value: src.slice(i, j) })
      i = j
      continue
    }

    if (ch === '<') {
      if (src[i + 1] === '=') { tokens.push({ type: 'LE' }); i += 2; continue }
      if (src[i + 1] === '>') { tokens.push({ type: 'NE' }); i += 2; continue }
      tokens.push({ type: 'LT' }); i++; continue
    }
    if (ch === '>') {
      if (src[i + 1] === '=') { tokens.push({ type: 'GE' }); i += 2; continue }
      tokens.push({ type: 'GT' }); i++; continue
    }
    if (ch === '=') { tokens.push({ type: 'EQ' }); i++; continue }
    if (ch === '+') { tokens.push({ type: 'PLUS' }); i++; continue }
    if (ch === '-') { tokens.push({ type: 'MINUS' }); i++; continue }
    if (ch === '*') { tokens.push({ type: 'STAR' }); i++; continue }
    if (ch === '/') { tokens.push({ type: 'SLASH' }); i++; continue }
    if (ch === '^') { tokens.push({ type: 'CARET' }); i++; continue }
    if (ch === '(') { tokens.push({ type: 'LPAREN' }); i++; continue }
    if (ch === ')') { tokens.push({ type: 'RPAREN' }); i++; continue }
    if (ch === ',') { tokens.push({ type: 'COMMA' }); i++; continue }
    if (ch === ':') { tokens.push({ type: 'COLON' }); i++; continue }

    tokens.push({ type: 'UNKNOWN', value: ch })
    i++
  }

  tokens.push({ type: 'EOF' })
  return tokens
}
"}

