const COMPARISON_OPS = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])

function rankKind(k) {
  return k === 'number' ? 0 : k === 'text' ? 1 : 2
}

function compareValues(l, r) {
  if (l.kind === r.kind) {
    if (l.kind === 'number') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
    if (l.kind === 'text') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
    // boolean: false below true
    if (l.value === r.value) return 0
    return l.value ? 1 : -1
  }
  const d = rankKind(l.kind) - rankKind(r.kind)
  return d < 0 ? -1 : d > 0 ? 1 : 0
}

