  if (isError(l)) return l
  if (isError(r)) return r
  const ln = toNumber(l)
  if (isError(ln)) return ln
  const rn = toNumber(r)
  if (isError(rn)) return rn
  let res
  switch (op) {
    case 'PLUS': res = ln.value + rn.value; break
    case 'MINUS': res = ln.value - rn.value; break
    case 'STAR': res = ln.value * rn.value; break
    case 'SLASH':
      if (rn.value === 0) return err('#DIV/0!')
      res = ln.value / rn.value
      break
    case 'CARET': res = Math.pow(ln.value, rn.value); break
  }
  if (!Number.isFinite(res)) return err('#DIV/0!')
  return num(res)
