  switch (node.type) {
    case 'addr':
      if (parseAddress(node.address)) out.add(node.address)
      break
    case 'range': {
      const addrs = expandRange(node.start, node.end)
      if (addrs) for (const a of addrs) out.add(a)
      break
    }
    case 'unary':
      collectRefs(node.expr, out)
      break
    case 'binary':
      collectRefs(node.left, out)
      collectRefs(node.right, out)
      break
    case 'call':
      for (const a of node.args) collectRefs(a, out)
      break
    default:
      break
  }
}

export function computeDeps(cells) {
  const result = new Map()
  for (const [address, content] of cells) {
    if (content.startsWith('=')) {
      const ast = parseFormula(content.slice(1))
      if (ast) {
        const found = new Set()
        collectRefs(ast, found)
        result.set(address, sortAddresses([...found]))
        continue
      }
    }
    result.set(address, [])
  }
  return result
