/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import fs from 'node:fs'
import { parseSheet, CliError } from './sheet.js'
import { evaluateAll } from './evaluate.js'
import { computeDeps } from './deps.js'
import { formatValue } from './format.js'
import { sortAddresses } from './address.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('usage: cli.js values|deps')
    return
  }

  const input = fs.readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof CliError) {
      fail(`line ${e.line}: ${e.message}`)
      return
    }
    throw e
  }

  const addrs = sortAddresses([...cells.keys()])
  let output

  if (mode === 'values') {
    const values = evaluateAll(cells)
    output = addrs.map((a) => `${a}=${formatValue(values.get(a))}\n`).join('')
  } else {
    const deps = computeDeps(cells)
    output = addrs
      .map((a) => {
        const ds = deps.get(a) || []
        return ds.length ? `${a}: ${ds.join(' ')}\n` : `${a}:\n`
      })
      .join('')
  }

  process.stdout.write(output)
  process.exit(0)
}

main()
"}

